from robot.libraries.BuiltIn import BuiltIn, RobotNotRunningError
from taf.ul.ettf.utils.exception import LibraryError


class NoVarNameSelected(LibraryError):
    pass


class TrackedVarValueUnknown(LibraryError):
    pass


class VarManager(object):
    def __init__(self, var_name=None, default_var_value=None):
        self._var_name = var_name
        self._default_var_value = default_var_value

    def _get_var_from_robot_environment(self):
        try:
            return BuiltIn().get_variable_value('${}'.format(self._var_name))
        except (RuntimeError, RobotNotRunningError):
            return None

    def set_var_name(self, var_name):
        self._var_name = var_name

    def set_default_var_value(self, default_var_value):
        self._default_var_value = default_var_value

    def get_variable(self):
        if self._var_name is None:
            raise NoVarNameSelected('No variable name specified',
                                    'Please set tracked name before trying to read value')

        var_value_from_robot_environment = self._get_var_from_robot_environment()
        if var_value_from_robot_environment is not None:
            return var_value_from_robot_environment

        if self._default_var_value is not None:
            return self._default_var_value

        raise TrackedVarValueUnknown('No given name found',
                                     'VarManager could not retrieve any information from this name reference')


robot_variable_manager = VarManager
